          "id": "T1-M01-S01",
          "title": "Australian agricultural regions and enterprise suitability",
          "theory": [
            "Australian agriculture is spread across many regions because different enterprises need different combinations of climate, land, water, soils and access to markets. An enterprise is more suitable when local conditions support reliable production of the desired product. For example, grazing may suit broad areas where animals can use pasture, while cropping is often concentrated where soils, rainfall, temperature, plains and water availability support plant growth and machinery access. Suitability is not based on one factor alone.",
            "To compare regions, first examine climatic and environmental factors. Rainfall affects pasture and crop growth, but its timing and reliability also matter. Temperature influences which plants and animals can perform well. Soil type affects drainage, nutrient supply, root growth and trafficability. Water availability can support production but may also create limits when demand is high or supply is variable. Landform matters because flatter plains may be easier to crop, while other country may be better suited to grazing. Students should explain how these factors work together rather than simply naming them.",
            "Economic and market considerations also shape enterprise choice. Producers consider whether products can be sold locally, processed nearby or transported to wider markets. Distance, infrastructure and changing prices can affect whether an otherwise suitable enterprise remains practical. However, this section does not use unverified figures, named export markets or rankings.",
            "Regions also face different challenges. Climate variability, pests, disease build-up, nutrient deficiencies, water use and market fluctuations can affect production. Management responses may include crop rotation to support soil health and reduce disease build-up, rotational grazing to manage pasture use, and technology to improve monitoring or production decisions. Some enterprises, such as vineyards, also require long-term establishment and planning. A sound regional comparison therefore links environmental suitability, market access and likely challenges, then explains why one enterprise may fit a region better than another without claiming that any region is automatically best."
          ],
