          "id": "T1-M02-S02",
          "title": "The six integrated pest management strategies",
          "theory": [
            "Integrated pest management (IPM) is an approach that uses several types of control to manage pests. Its aim is not simply to remove every pest. Instead, it seeks a practical balance that is economically viable, environmentally responsible and socially acceptable.",
            "Cultural control changes farming practices or production conditions so that pests are less likely to establish, survive or cause serious damage. Physical or mechanical control uses barriers, traps, direct removal or other physical actions to reduce pest access or numbers. Biological control uses living organisms, such as predators, parasites or pathogens, to help suppress a pest population.",
            "Chemical control uses substances to manage pests. In IPM, chemical control is treated as one available option rather than the whole plan. Genetic control uses pest-resistant plant varieties or animal breeds so that the production system is less vulnerable to particular pests. Regulatory control uses rules or restrictions, including quarantine or movement controls, to reduce the chance that pests will enter or spread between places.",
            "Each category provides a different type of response. A barrier acts differently from a predator, and a resistant variety acts differently from a movement restriction. This means the categories should not be confused, even when they contribute to the same management goal.",
            "IPM strategies are most effective when they are combined. Using more than one category can reduce reliance on a single method and allow the weaknesses of one strategy to be supported by the strengths of another. For example, changing production conditions may reduce pest pressure, while a physical barrier limits access and biological control helps suppress pests that remain. The most suitable combination depends on the production context, the pest problem and the evidence available.",
            "This section explains the six strategy categories only. Exact products, rates, treatments, protective equipment, local biosecurity requirements and animal procedures are not provided here. Teacher to confirm any local requirements, approved practices or missing details before practical application."
          ],
