          "id": "T1-M02-S03",
          "title": "Combining controls and responding to failure",
          "theory": [
            "Integrated pest management (IPM) is strongest when several controls are combined rather than relying on one response. The first step is to identify the harmful organism or production issue accurately. Evidence about the organism matters because different controls act in different ways. For example, ladybirds feeding on aphids are a biological control, while changing production practices is cultural control and using a barrier or trap is physical control.",
            "A justified IPM plan should include at least three different control categories. These may come from cultural, physical, biological, chemical, genetic or regulatory controls. The aim is not to include categories at random. Each control should have a clear role in reducing the issue, limiting spread, protecting production or supporting beneficial organisms. The mix should also suit the production context and consider possible environmental effects.",
            "Combining controls improves decision-making because one control may not work fully on its own. A physical barrier may reduce access but not remove organisms already present. A biological control may reduce a pest population, but its effect may be slower or depend on suitable conditions. Another category can support the plan by acting on a different part of the problem.",
            "A strong justification explains what each control contributes, why the combination is suitable and what trade-offs need to be considered. It should avoid unsupported claims that a control will always succeed.",
            "IPM also requires a contingency. If one strategy fails, the plan should be reviewed using new evidence. The failure may mean the issue was identified incorrectly, the control was unsuitable, conditions changed or the control did not act as expected. The response is to revise the mix, strengthen another category or replace the failed strategy with a more suitable option. Exact products, rates, treatment sequences, local procedures and safety requirements are Teacher to confirm and currently verify."
          ],
