          "title": "Reading livestock graphs and identifying trends",
          "theory": [
            "Livestock graphs organise data so patterns can be seen more clearly. Begin by reading the graph title, then check both axes. The horizontal axis often shows time, such as months or years, while the vertical axis shows the measured quantity. Always note the units because a value could represent individual animals, thousands of animals or a percentage. Check the full time period before describing a trend; focusing on only two nearby points can give a misleading impression.",
            "A trend is the overall direction shown across the period. An increase means values generally move upward, while a decrease means they generally move downward. Fluctuation means the values rise and fall rather than moving steadily in one direction. A peak is the highest value shown, and a low point is the smallest. A graph may contain short-term changes within a broader trend, so describe both when relevant. For example, values might fluctuate from year to year but still show an overall decrease.",
            "Keep observation separate from explanation. An observation states what the graph shows, such as “livestock numbers rose between the first and final data points”. An explanation proposes a reason, such as improved seasonal conditions. The graph alone usually cannot prove that reason. It shows that changes occurred, not exactly why they occurred.",
            "Possible influences on livestock numbers include seasonal conditions, feed availability and market demand. These should be presented cautiously using language such as “may have”, “could have” or “one possible factor is”. Reliable explanations require supporting evidence beyond the graph.",
            "The supplied learning materials use data from September 2021 to September 2023 and a September 2023 ABS release. Those figures, rankings and conclusions must not be treated as current unless they are checked against a current source. The key skill is to read the evidence accurately, describe the pattern clearly and avoid claiming more than the data can support."
          ],
