          "id": "T1-M03-S03",
          "title": "Using trend evidence in marketing decisions",
          "theory": [
            "Trend evidence can improve a marketing decision, but it must be used carefully. Start by stating only what the data establishes. After reading the axes, units and time period, describe the direction and size of the recorded change. This is evidence. Do not turn the pattern into a claim about cause or future prices. A graph may show that livestock numbers changed, but it does not prove why they changed or what buyers will pay next.",
            "The next step is to connect the evidence with the enterprise context. Relevant context may include the producer’s need for stability, flexibility, buyer reach, available time, ability to meet requirements, transport logistics and customer trust. These factors help compare selling channels. For example, a producer facing uncertain supply may value flexibility, while one seeking predictable planning may place more weight on stability. This is an inference because it applies the evidence to a particular situation.",
            "A strong recommendation follows a clear sequence. First, state the observed trend accurately. Second, explain a cautious inference using words such as “may”, “could” or “suggests”. Third, compare the important trade-offs between suitable selling channels. Finally, identify what additional information is needed before acting. This might include current prices, contract conditions, buyer requirements, transport capacity, customer access or the reliability of the trend beyond the recorded period.",
            "Uncertainty should be made visible rather than ignored. Older data may not represent current conditions, and one trend may not continue. A selling channel with wider reach may also involve more workload and logistics. A channel offering stability may reduce flexibility or impose requirements. Therefore, a justified decision does not claim certainty or guaranteed profit. It explains what is known, what is inferred, what remains uncertain and why one option appears more suitable for the stated enterprise context."
          ],
