          "id": "T1-M04-S01",
          "title": "Clear and unbiased agricultural market surveys",
          "theory": [
            "A market survey is used to collect information about consumers before making marketing decisions. In agriculture, a survey can investigate preferences, buying habits and needs related to a chosen product. A clear purpose keeps the survey focused. For example, the purpose might be to find which product features influence purchase decisions, rather than simply asking whether people “like” the product.",
            "The target group is the type of consumer the survey is intended to represent. Questions should suit that group and collect information relevant to the survey purpose. If the people who respond are very different from the intended customers, the results may not accurately represent the market being investigated.",
            "Survey wording should be clear, specific and neutral. A biased or leading question pushes respondents towards a preferred answer. For example, “Why is this high-quality product a good choice?” assumes the product is high quality and worth choosing. A more neutral question asks, “Which factors would influence your decision to purchase this product?” Suitable response options might include quality, price, convenience or another relevant factor. Options should be distinct and broad enough to avoid forcing an inaccurate answer. An “other” option can be useful when the listed choices may not cover every response.",
            "Before collecting responses, students can predict what they expect to find. A prediction is an informed expectation, not a result. After responses are collected, the actual results can be organised and compared with the prediction. A difference between the two is useful evidence because it may reveal that initial assumptions were inaccurate.",
            "Survey conclusions must match the strength of the evidence. A small sample may miss important views, while an unrepresentative sample may overstate the preferences of one group. Results should therefore be described cautiously. They show what the surveyed group reported, not automatically what all consumers believe. Distribution procedures, respondent numbers and any local survey requirements are Teacher to confirm."
          ],
          "takeaways": [
            "Begin with a clear survey purpose and relevant target group.",
            "Use clear, specific and neutral questions.",
            "Provide distinct response options that allow accurate answers.",
            "Keep predictions separate from actual survey results.",
            "Limit conclusions when the sample is small or unrepresentative."
          ],
