          "title": "Comparing plant production systems",
          "theory": [
            "Plant production systems can be compared by examining their resource needs, level of control, costs, environmental aims, outputs and limitations. No single system is automatically best or most sustainable in every situation.",
            "Glasshouse production gives growers greater control over conditions such as temperature, humidity and light. This can help create more consistent growing conditions and reduce exposure to some outside weather changes. However, glasshouses require setup materials, equipment and ongoing running resources. Their value depends on whether the extra control justifies the added cost, energy use and management workload.",
            "Organic production avoids synthetic chemicals and instead uses approaches such as natural fertilisers and pest-control methods. Its aims may include supporting soil health and biodiversity. Biodynamic production shares some features with organic systems but adds further practices, including particular composting approaches and ideas linked to lunar cycles. These systems may appeal to producers and consumers who value particular production methods, but they can also face challenges such as lower or less predictable yields and certification requirements. Claims about certification or environmental performance must be verified rather than assumed.",
            "Commercial worm farming uses worms to process suitable organic waste. The system produces worm castings and liquid fertiliser, which may be used as soil inputs or sold as additional products. This can give organic waste another use and may create another enterprise output. However, the system still requires suitable resources, management and a reliable use or market for its products.",
            "A fair comparison considers both benefits and trade-offs. Glasshouses provide greater environmental control but require significant resources. Organic and biodynamic systems focus more strongly on soil, biodiversity and selected production practices but may involve yield and certification challenges. Worm farming can reduce waste and produce useful outputs, but it does not replace every other production need. The most suitable system depends on the enterprise purpose, available resources, required outputs and acceptable limitations."
          ],
