          "title": "Comparing animal production systems and trade-offs",
          "theory": [
            "Animal production systems should be compared through their land use, inputs, management needs, production efficiency, welfare considerations, environmental effects, costs and relationship with consumer demand. No system is universally superior because each involves different benefits and trade-offs.",
            "Rangeland beef systems use pasture spread across larger areas of land. Animals obtain much of their feed from the available grazing environment, so production is closely connected to land, pasture and seasonal conditions. These systems may use fewer concentrated feeding inputs, but they require sufficient suitable land and management across a broad area.",
            "Feedlot beef systems keep cattle in confined areas and provide controlled, high-energy feeding. This can support more consistent management of feed and production within a smaller land area. However, feedlots require substantial feed inputs, infrastructure and close management. Concentrating animals and resources may also create environmental and welfare considerations that need to be assessed rather than assumed.",
            "Caged layer systems keep hens in enclosures and can use housing space efficiently. They may allow controlled management of feeding, egg collection and the production environment. Their limitations include welfare concerns related to confinement and the need to manage concentrated waste and resources.",
            "Free-range layer systems allow hens access to outdoor roaming areas. This may respond to consumer interest in particular animal-production conditions, but it requires more land and additional management of the outdoor environment. Production efficiency, costs and risks may differ from caged systems, so free-range should not automatically be described as better in every measure.",
            "A strong comparison avoids judging a system from one feature alone. Greater land access may involve more land and management, while concentrated production may improve space or input control but create other welfare or environmental concerns. Consumer demand can influence which products producers consider, but demand does not remove production costs or management responsibilities. Current welfare standards, legal requirements, exact costs, productivity figures and local procedures must be verified before making practical claims."
          ],
