          "id": "T1-M05-S03",
          "title": "Term 1 topic-test preparation: describe, explain and compare",
          "theory": [
            "Effective topic-test preparation involves retrieving key knowledge and shaping it to match the question. Term 1 concepts include regional suitability, niche agricultural industries, beneficial and harmful organisms, integrated pest management, graph trends, sustainability, marketing strategies, surveys, value adding, promotion and production systems. Instead of memorising isolated sentences, organise each topic around definitions, features, examples, causes, effects and trade-offs.",
            "The command term tells you how to construct the response. To describe, state what something is and give its important features. A description of a glasshouse system could identify it as a controlled plant-production environment and mention regulation of temperature, humidity and light. Description does not require a long discussion of causes unless the question also asks for them.",
            "To explain, show why or how something occurs. Link a cause to an effect using phrases such as “This is because” and “This leads to”. For example, combining several integrated pest management methods may improve pest control because the methods act in different ways. This leads to less reliance on one control that could fail.",
            "To compare, identify both similarities and differences using the same criteria. For example, rangeland and feedlot beef systems both produce cattle, but they differ in land use, feed inputs and production control. A strong comparison moves between the two options rather than writing two unrelated descriptions.",
            "Evidence and examples make answers more precise. Use “For example” to support a general point, but choose examples that directly answer the question. Before finishing, check that every sentence contributes to the required task. A useful response sequence is: identify the concept, provide relevant evidence or an example, add a causal link where required, and return to the question. Current market claims, legal requirements, local procedures, assessment marks, test format and dates must not be assumed and are Teacher to confirm or currently verify."
          ],
