          "id": "T2-M06-S02",
          "title": "Calculating a gross margin step by step",
          "theory": [
            "A gross margin is a calculation used to compare the income and variable costs associated with a cropping enterprise. The formula is: gross margin = total income − total variable costs. It is usually expressed in dollars per hectare ($/ha), so all income and cost figures must refer to the same area.",
            "First, calculate the expected income per hectare. Use the formula: income per hectare = expected yield (t/ha) × market price ($/t). The units help check the calculation. When tonnes per hectare are multiplied by dollars per tonne, the tonnes cancel, leaving dollars per hectare. In the supplied wheat learning scenario, the expected yield is 4 t/ha and the market price is $300/t. Therefore, 4 t/ha × $300/t = $1,200/ha.",
            "Next, add all applicable variable costs per hectare. These may include seed, fertiliser, herbicide or spray, fuel and labour. Only costs included in the scenario should be added. In the supplied example, the listed variable costs are $80, $150, $70 and $50 per hectare. The total is $80 + $150 + $70 + $50 = $350/ha.",
            "Finally, subtract the total variable costs from the total income: $1,200/ha − $350/ha = $850/ha. The gross margin for this learning scenario is therefore $850/ha.",
            "Arithmetic should be checked before interpreting the result. Recalculate the multiplication, add the costs in a different order, and confirm that every value is expressed per hectare. A useful reverse check is to add the gross margin and variable costs: $850/ha + $350/ha = $1,200/ha, which matches the calculated income.",
            "Gross margin is not the same as whole-farm profit. It subtracts variable costs from income but does not include fixed costs or every expense faced by a farm business. It should therefore be interpreted as one financial comparison tool rather than a complete measure of profitability."
          ],
