          "id": "T2-M07-S01",
          "title": "Crop monitoring indicators and patterns",
          "theory": [
            "Crop monitoring combines regular observation with data collection to support decisions and help protect yield. A single observation can show what is visible at one moment, but repeated observations provide stronger evidence because they reveal whether a condition is spreading, improving, worsening or remaining stable.",
            "Useful indicators include plant population and gaps, leaf colour, pest or disease damage, weed pressure, growth stage and moisture condition. Plant population observations can show whether plants are distributed evenly or whether gaps occur in particular areas. Leaf colour can also provide clues. Yellowing may indicate nitrogen deficiency or waterlogging, while purple colouring may point to phosphorus issues. These signs are possible indicators only and must not be treated as certain diagnoses. Similar symptoms can have different causes, so further evidence is needed before drawing a conclusion.",
            "Visible damage can also help identify patterns. Chewed leaf edges or holes may indicate feeding damage. Fungal leaf spots may appear as marked areas on leaves. Dense weed growth can show where crop competition is stronger, while wilting or dry plants may indicate an unfavourable moisture condition. Each observation should describe what is visible rather than claim a cause that has not been confirmed.",
            "Patterns become clearer when observations are compared over time and across different paddock areas. For example, a symptom occurring only in one low area may suggest a different issue from the same symptom appearing evenly across the crop. Comparing affected and unaffected areas can help students identify what further evidence is required.",
            "Good monitoring therefore involves recording clear observations, noting where indicators occur and comparing results. The purpose is not to prescribe treatment but to build enough evidence to support a reasoned next decision. Any local practical action, sampling method, equipment use or response remains teacher-controlled."
          ],
