          "id": "T2-M07-S03",
          "title": "Evidence-based monitoring decisions and prioritisation",
          "theory": [
            "Regular crop monitoring combines observation and data collection so possible problems can be identified early, before yield is significantly reduced. Monitoring supports better decisions because it helps distinguish an isolated observation from a developing pattern. It can also reduce wasted inputs, such as unnecessary spraying or watering, by directing attention and resources towards areas where further investigation is justified.",
            "Visible signs may include yellowing leaves, chewed edges or holes, dense weed growth, wilting or dry plants, and fungal leaf spots. These signs are indicators only. They do not confirm a cause or diagnosis, and appearance alone is not enough to justify a response.",
            "When several crop issues are observed, students can compare them and decide which one should be investigated first. A defensible priority is not simply the issue that looks most dramatic. It should be based on the observed pattern, how much of the crop appears affected, whether the condition is changing over time, its possible effect on crop growth or yield, and the strength or limits of the available evidence.",
            "For example, an indicator affecting a large area and becoming more widespread may deserve earlier investigation than a small, stable patch. However, the evidence may still be incomplete. Students should clearly separate what has been observed from what is only suspected.",
            "A strong monitoring decision identifies one priority, explains what could happen if the issue continues, and states what further evidence is needed before concluding a cause or considering a response. This approach supports targeted resource use and may help reduce unnecessary inputs and runoff while supporting long-term soil and plant health.",
            "Monitoring therefore guides investigation rather than providing an automatic diagnosis or treatment. Local thresholds, actions and practical directions remain teacher-controlled."
          ],
