            "Pests damage plants directly. The supplied source examples are aphids, red-legged earth mite and armyworm. These are learning examples only and must not be used to identify an unseen, photographed or collected specimen when the evidence is absent or unclear.",
            "Monitoring is the process of gathering evidence before making a decision. Useful observations include visible damage, possible pest presence, where the signs occur and whether the pattern changes over time. Chewed leaves, discolouration, reduced growth and other visible signs may indicate that a problem is present, but appearance alone cannot confirm a pest, disease or cause. Students should separate what has been observed from an explanation that remains unconfirmed.",
            "Distribution provides important evidence. Damage affecting a few plants may represent a different situation from damage spread across a larger area. Repeated monitoring can also show whether the pattern is increasing, decreasing or remaining stable. These comparisons help determine what further evidence is required.",
