            "Broad disease-management categories in the sources include resistant varieties, crop or pasture rotation, fungicides and reducing residue carryover. Integrated management means considering more than one suitable broad category in relation to the available evidence, the production system and possible disease spread. It does not mean that every category should be used in every case.",
            "A defensible explanation may state that resistant varieties and rotation could be considered as broad categories where the evidence and production system support them. It may also recognise that fungicides or residue management are other categories, without selecting a product, rate, timing or procedure. Any management discussion must remain conditional because the cause has not been confirmed and local requirements may differ.",
