            "Maintaining ground cover is a broad sustainability strategy because plant material can help protect the soil surface. Ground cover may reduce the soil’s exposure to conditions that contribute to erosion and can support the land’s longer-term productive capacity. Changes in ground cover can be examined by comparing supplied hypothetical observations over time. Increasing bare ground or declining plant cover may indicate growing pressure, while signs of renewed cover may suggest recovery. These patterns remain indicators and should not be treated as complete explanations.",
            "Rotational grazing is a broad strategy in which grazing pressure is managed across different areas to support pasture recovery and ground cover. The principle involves allowing grazed areas an opportunity to recover rather than applying continuous pressure to the same area. It does not provide a universal paddock sequence, movement schedule, grazing duration or stocking rate.",
