            "Crop or pasture rotation, reduced tillage with stubble retention, and precision application are broad sustainability strategy categories. Each may respond to a different production or environmental pressure, but none guarantees a particular outcome. A sound comparison links the strategy to supplied evidence, explains possible benefits and recognises limits and trade-offs.",
