            "Evaluating crop or pasture performance requires evidence from across the production system. Plant structures and growth patterns, soil health, monitoring records, weed, pest or disease pressure, sustainability strategies and financial evidence can all be connected. One isolated observation rarely explains performance by itself because several factors may interact.",
