            "Financial evidence adds another part of the evaluation. Gross margin equals income minus variable costs. It can help compare supplied crop or pasture scenarios, but it does not equal whole-farm profit because fixed costs are excluded. Any supplied yields, prices, income figures, costs or gross margins are learning-scenario evidence only, not verified current market values or local-farm facts.",
