          "id": "T2-M10-S02",
          "title": "Four-criteria evaluation",
          "theory": [
            "Agricultural systems can be evaluated using four connected criteria: productivity, sustainability, profitability and risk management. Each criterion provides different evidence, so no single result proves that a system performs well overall.",
            "Productivity describes how effectively a system produces plant material or output. Supplied indicators may include yield, biomass, regrowth and uniformity. Strong productivity evidence can show that a crop or pasture is performing well in one area, but it does not automatically show that the system is sustainable, profitable or well protected from risk.",
            "Sustainability considers the system’s longer-term environmental condition. Supplied evidence may include soil condition, ground cover, water impacts and biodiversity. A productive system may still be unsustainable if its performance is linked with declining soil condition, reduced cover, water impacts or lower biodiversity. These indicators describe possible strengths or pressures and must not be treated as diagnoses from appearance alone.",
            "Profitability evidence includes income, variable costs and gross margin. Gross margin equals income minus variable costs. It excludes fixed costs and is therefore not the same as whole-farm profit. All supplied yields, prices, income figures, costs and gross margins are learning-scenario evidence rather than verified current market or local-farm values. A high-yielding system may have a weaker gross margin if its variable costs are also high.",
            "Risk management considers evidence about climate, biological, market and dependence risks. A system that relies heavily on one crop, one market condition or one source of performance may be more exposed if circumstances change. Risk evidence does not predict a certain outcome, but it helps students examine vulnerability and uncertainty.",
            "A defensible evaluation compares systems across all four criteria, identifies trade-offs and makes a conditional recommendation. Decisions may also be adjusted through a season as new evidence becomes available. This is an evaluation principle, not a local timing rule or procedure. Students should state what the evidence supports, what remains uncertain and what further evidence would be needed before changing a decision."
          ],
          "takeaways": [
            "Evaluate systems using productivity, sustainability, profitability and risk management.",
            "No single criterion proves that a system performs well overall.",
            "High productivity does not guarantee sustainability or profitability.",
            "Gross margin excludes fixed costs and is not whole-farm profit.",
            "Make conditional recommendations and adjust judgements as evidence changes."
          ],
