          "id": "11.2",
          "title": "Reading and constructing a prime-lamb pedigree",
          "theory": [
            "A prime-lamb pedigree is a labelled diagram that shows how selected parent breeds are linked across a breeding programme. Read the diagram in the direction shown by its arrows or connecting lines. Each mating pair should lead clearly to its offspring, and each generation should be separated so the breeding sequence is easy to follow. The diagram must show parent-to-offspring relationships rather than presenting a loose list of breeds.",
            "In the Task 3 structure, the pedigree begins with a Merino ewe and a variable ram breed selected by the student. Their offspring is labelled as a first-cross ewe. This first-cross ewe is not the same as the original Merino ewe or the ram used in the first mating. She carries characteristics from both parent breeds and becomes the female used in the second stage of the programme.",
            "The second stage links the first-cross ewe with a student-selected terminal sire. The terminal sire is the last sire used in this breeding structure. Their offspring are labelled as prime lambs. In this structure, these prime lambs are produced as the final offspring and are not retained as breeding females to continue the pedigree. This distinguishes the terminal sire’s role from the variable ram used to produce the first-cross ewe.",
            "Students must choose the variable ram and terminal-sire breeds themselves. A sound choice cannot be justified by simply stating that a breed is popular or suitable. For every breed shown, use evidence from the authorised sources to identify relevant characteristics, state whether its main product is wool, meat or both, and explain what it contributes to the breeding programme. The justification should connect the breed evidence to its exact role in the pedigree.",
            "When constructing the diagram, label both parents at each mating, use clear links to the correct offspring and keep the first-cross ewe visually distinct from the terminal sire and prime lambs. Do not add unsupported breed claims. Any local or current requirement is Teacher to confirm."
          ],
          "takeaways": [
            "A pedigree must show a clear direction and accurate parent-to-offspring links.",
            "The first mating is a Merino ewe crossed with a student-selected variable ram to produce a first-cross ewe.",
            "The first-cross ewe is then crossed with a student-selected terminal sire to produce prime lambs.",
            "Each breed choice must be justified using sourced characteristics, its main product and its contribution to the programme.",
            "The terminal sire is the final sire in this structure, and its offspring are not retained as breeding females within the pedigree."
          ],
