          "title": "Nutrients, digestion and energy",
          "theory": [
            "Sheep need a balanced supply of nutrients and water to support growth, movement, digestion, body maintenance and reproduction. In a prime lamb enterprise, nutrition affects how well lambs grow and how effectively adult sheep maintain condition and support production. Nutritional needs are not identical for every animal, so the quality of the available feed must be considered alongside the sheep’s stage of production.",
            "Energy is needed for movement, warmth, digestion, growth and reproduction. Sheep obtain energy mainly from carbohydrates and fats in their diet. Green, leafy pasture is generally more digestible and provides more useful energy than old, stemmy pasture. Stemmy material can fill the rumen but may provide less available nutrition because it contains more fibre and is harder to digest.",
            "Protein supplies materials needed for growth and the development and repair of body tissues. It is particularly important when sheep are growing or supporting demanding production stages. Legumes such as clover, lucerne and lupins are identified in the source material as feeds that may contribute useful protein. Their suitability in a local feeding programme is Teacher to confirm.",
            "Fibre is essential because sheep are ruminants. Feed enters the rumen, where digestion begins with the help of microorganisms that break down plant material. Fibre supports normal rumen function and provides bulk, but very fibrous, low-quality feed may be digested slowly and may not supply enough useful energy or protein for sheep with higher nutritional demands.",
            "Vitamins and minerals support body processes such as growth, bone development, immunity and reproduction. They are required in smaller amounts than energy or protein, but shortages can still affect animal performance. Water is also essential. It supports digestion, regulates body temperature and is necessary for survival.",
            "Good nutrition therefore depends on balance. A feed may contain fibre but provide limited protein or energy, while another may be more digestible and nutrient-dense. Specific rations, supplements and local feeding decisions are Teacher to confirm rather than assumed from general nutrient principles."
          ],
          "takeaways": [
            "Sheep require energy, protein, fibre, vitamins, minerals and water for normal body functions and production.",
            "The rumen helps sheep digest plant material with the assistance of microorganisms.",
            "Leafy, digestible feed generally provides more useful nutrition than old, stemmy feed.",
            "Fibre is necessary, but excessive low-quality fibre can slow digestion and limit available energy.",
            "Nutritional needs change with growth and other stages of production."
          ],
