          "id": "12.2",
          "title": "Matching feed to changing requirements",
          "theory": [
            "Sheep do not require the same level or type of feed at every stage of production. Their feed requirements change according to whether they are maintaining body condition, growing, pregnant or lactating. Matching feed to these changing demands means considering both the quality of the feed and the quantity available.",
            "Maintenance is the level of feeding needed to support basic body functions and help an animal maintain condition when it is not growing rapidly or supporting another high-demand stage. Feed that is suitable for maintenance may not provide enough useful nutrition for growing lambs, pregnant ewes or lactating ewes. These classes generally have higher demands because they are building body tissue, supporting developing lambs or producing milk.",
            "Growing lambs need feed that supports steady growth and body development. Pregnant ewes require increasing nutritional support as pregnancy progresses, while lactating ewes need feed that supports milk production and helps them maintain condition. The exact feeding response depends on the animal’s stage, current condition and the feed available. Local decisions are Teacher to confirm.",
            "Pasture quality strongly affects whether requirements are met. Green, leafy pasture is generally more digestible and provides more useful nutrition than old, dry or stemmy pasture. Legume-rich pasture may provide higher protein than grass-only pasture and may be useful for animals with greater production demands. However, the presence of a particular pasture plant does not automatically mean the whole paddock will meet requirements.",
            "Quantity matters as well as quality. High-quality pasture cannot meet demand if too little is available, while a large quantity of low-quality pasture may fill the rumen without supplying enough useful nutrition. Sheep may then lose condition or grow more slowly.",
            "Supplements may be considered when available pasture does not match the needs of a particular class of sheep. The purpose of supplementation is to fill an identified gap, not simply to add more feed. Producers compare the sheep’s production stage, condition, pasture quality and pasture quantity before deciding whether additional feed may be required. Specific supplements, ration amounts and local feeding recommendations are Teacher to confirm."
          ],
          "takeaways": [
            "Feed requirements change between maintenance, growth, pregnancy and lactation.",
            "Higher-demand classes need feed that provides more useful nutrition than maintenance feeding alone.",
            "Both pasture quality and pasture quantity affect whether sheep requirements are met.",
            "Supplements are used to address an identified feed gap rather than being added automatically.",
            "Animal condition and production stage help guide feeding decisions."
          ],
          "boundary": "Section 12.2 includes changing feed requirements for maintenance, growth, pregnancy and lactation; the importance of body condition; the relationship between pasture quality and quantity; and the purpose of supplements in filling identified feed gaps. It excludes detailed nutrient functions taught in section 12.1, pasture-sampling methods taught in section 12.3, farm-specific rations, ration amounts, animal or reproduction procedures, welfare rules, safety controls, dates and unsupported current recommendations. Any local supplement choice, ration or current feeding requirement is Teacher to confirm.",
