          "id": "13.2",
          "title": "Linking management decisions across the production cycle",
          "theory": [
            "Management decisions in a prime lamb enterprise are connected across the production cycle. A decision made at one stage can affect feed demand, reproduction, lamb growth and later production outcomes. For this reason, producers need to think in sequences rather than treating each stage as a separate event.",
            "Seasonal feed conditions are one important link. The amount and quality of pasture available can influence whether sheep requirements are likely to be met during reproduction, lamb development and ewe recovery. If feed supply does not match demand at one stage, the effects may continue into later stages. For example, poor ewe condition before a reproductive stage may influence later performance, while limited feed during lamb growth may affect progress towards production goals.",
            "The stages of reproduction also connect with one another. Joining influences the expected lambing period, and lambing outcomes affect the number and type of lambs that continue through later growth stages. Weaning separates the nutritional needs of lambs and ewes, allowing their condition and growth to be considered independently. Decisions made around one stage should therefore account for what the next stage will require.",
            "Monitoring provides evidence for these decisions. Producers may observe pasture condition, feed availability, ewe condition, lamb growth and differences between groups. Records allow these observations to be compared over time. A single observation may identify a possible concern, but repeated or linked records can show whether a pattern is developing and whether an earlier decision had the intended effect.",
            "Consequences can occur when timing, feed supply and animal requirements do not align. Lambs may enter a growth stage when feed quality is limited, ewes may not recover condition as expected, or planned marketing opportunities may become harder to meet. These outcomes are not caused by one factor alone, so evidence from several stages should be considered together.",
            "Effective management therefore involves reviewing the sequence: what happened earlier, what is happening now and what the next stage will require. Local actions and requirements are Teacher to confirm."
          ],
