          "id": "13.3",
          "title": "Technology for identification, monitoring and decisions",
          "theory": [
            "Technology can help prime lamb producers identify animals, collect measurements, organise records and notice patterns across the production cycle. Electronic identification, often shortened to EID, links an individual animal to a digital record. This allows observations and measurements to be stored against the correct animal rather than being treated only as information about the whole flock.",
            "EID records may be connected with information such as liveweight measurements, growth records, lambing history or other observations. When records are accurate and collected consistently, producers can compare animals or groups over time. This may help identify stronger or weaker performance, changes in growth, differences between groups or results that need further investigation.",
            "Weighing and scanning technologies provide measurements that can be added to these records. A single measurement gives information from one point in time, while repeated measurements can show a pattern. For example, several weight records can provide evidence about whether growth is changing. Scanning information may also help producers separate animals into groups with different requirements. The value of the technology comes from how the data are interpreted, not simply from collecting more information.",
            "Technology can support decisions by making records easier to retrieve, compare and review. It may reduce reliance on memory and help producers connect earlier management choices with later results. However, technology does not make decisions automatically or guarantee better outcomes. Data can be incomplete, entered incorrectly or interpreted without enough context. Equipment and software may also involve cost, maintenance, training and access limitations.",
            "Human judgement remains essential. Producers need to check whether the information is reliable, consider seasonal conditions and animal requirements, and compare digital records with direct observations. A pattern in the data may suggest a question or possible response, but it does not prove a cause by itself. Technology is most useful when it strengthens evidence-based judgement rather than replacing it. Current legal requirements, equipment settings, operating procedures and local technology choices are Teacher to confirm."
          ],
