          "id": "15.3",
          "title": "Farm business reasoning: costs, gross margins and SWOT",
          "theory": [
            "Profitability reasoning compares the income earned from production with the costs required to produce that output. Sale income alone does not show whether an enterprise has performed profitably because the business may have incurred substantial costs to generate that income.",
            "A farm budget is an organised estimate or record of expected income and costs. It helps producers examine business options, test assumptions and compare planned results with actual records. The usefulness of a budget depends on the accuracy and consistency of the information included.",
            "Variable costs change with the amount produced. Source examples include feed supplements, animal health inputs, shearing, freight or marketing, and transport. Fixed costs generally remain even when output changes. Examples include rates, machinery repayments, farm insurance and permanent staff wages. These categories support business analysis, but actual farm classifications are Teacher to confirm from current records.",
            "Gross margin is calculated as enterprise income minus variable costs. In the supplied structure, total income equals the number sold multiplied by income per animal. Total variable costs equal the number produced multiplied by the combined per-animal variable costs. Gross margin is then found by subtracting total variable costs from total income.",
            "Gross margin is not the same as whole-farm profit because fixed costs are excluded. It can help compare enterprise options only when the assumptions, time period and included costs are consistent. A higher gross margin does not automatically decide what a farm should do because production evidence, welfare, WHS and longer-term consequences must also be considered.",
            "The sources identify three broad pathways for improving profitability: increasing income, reducing costs or improving efficiency. Each pathway requires evidence because a change that appears beneficial in one area may create consequences elsewhere.",
            "SWOT analysis supports broader reasoning. Strengths and weaknesses are internal features of the farm or enterprise, while opportunities and threats arise from outside it. SWOT entries should be evidence-based rather than invented claims about current markets, seasons or conditions. Actual prices, costs, lamb numbers, market conditions, assumptions and business decisions are Teacher to confirm."
          ],
