            "Deregulation means removing government controls from an industry. In the supplied lesson, Australian dairy deregulation occurred in 2000 and removed controls on milk prices and quotas. Before deregulation, state arrangements included a minimum farm-gate price. Afterwards, supply and demand had a greater influence on the price paid to producers.",
            "This change created both benefits and costs. Source-identified economic impacts included lower farm-gate prices for many producers, stronger pressure to improve efficiency, growth in larger export-focused farms, consolidation among milk processors and greater product diversity among businesses that remained. These changes did not affect every farm in the same way. A farm’s scale, production costs, location, access to buyers and ability to adapt could influence whether it managed the change successfully.",
            "The lesson also identifies important social effects. These included the loss of some small family farms, rural depopulation, financial stress, reduced community services and a shift from owner-operated farms towards more corporate farming. These impacts could spread beyond individual businesses because fewer farms and families may reduce demand for local schools, shops and services.",
