          "title": "Hormonal control of the oestrous cycle",
          "theory": [
            "The oestrous cycle is controlled by a sequence of hormones that coordinate changes in the ovaries, uterus and reproductive behaviour. The four stages are pro-oestrus, oestrus, metoestrus and dioestrus. These stages are linked because the effect of one hormone helps create the conditions for the next event in the cycle.",
            "During pro-oestrus, follicle-stimulating hormone, or FSH, is released from the pituitary gland. FSH stimulates follicles in the ovary to grow. As the follicles develop, they produce increasing amounts of oestrogen. Rising oestrogen prepares the reproductive tract and is linked with the signs of heat. It is also associated with the surge of luteinising hormone, or LH.",
            "Oestrus is the stage when heat behaviour is most evident. The LH surge triggers ovulation, which is the release of an ovum from a mature follicle. After ovulation, the remains of the follicle develop into a structure called the corpus luteum. This change occurs during metoestrus.",
            "The corpus luteum produces progesterone. During dioestrus, progesterone supports the uterine lining, supports pregnancy if fertilisation has occurred and suppresses further heat behaviour. If pregnancy does not occur, the uterus produces prostaglandin, also called PGF2alpha. Prostaglandin causes the corpus luteum to break down. Progesterone then falls, allowing follicle growth and the cycle to begin again. Each change can therefore be explained through the relationship between hormone levels, ovarian structures and reproductive responses.",
            "This hormone sequence can be used to understand why reproductive events occur in a predictable order. Synchronisation may be used to coordinate heat detection and breeding management across a group, but it does not replace sound management. Its success depends on animal health, nutrition, accurate records and qualified control. Any local practice, product use or management requirement is outside this section and must be confirmed by the teacher."
          ],
