          "id": "T4-M19-S01",
          "title": "Male reproductive anatomy and the sperm pathway",
          "theory": [
            "The male reproductive system works as a connected pathway that produces sperm, supports their development, adds fluids to form semen and allows semen to be deposited in the female reproductive tract.",
            "The testes are the main reproductive organs. Their key function is to produce sperm cells. They are located within the scrotum, which is the external sac that holds and protects the testes. The position of the testes in the scrotum helps maintain conditions suitable for normal sperm production.",
            "After sperm are produced, they move into the epididymis. This is a long, coiled structure attached to each testis. In the epididymis, sperm mature and are stored until they move further through the reproductive tract. The vas deferens is the tube that transports mature sperm away from the epididymis.",
            "As sperm travel through the reproductive tract, fluids from the accessory glands are added. These fluids combine with sperm to form semen. Semen therefore contains sperm cells and glandular fluids that support their transport. The pathway then continues through the penis, the organ that deposits semen. The sheath is the external fold of skin that surrounds and protects the penis when it is not extended.",
            "The pathway can be summarised as: sperm are produced in the testes, mature and are stored in the epididymis, travel through the vas deferens, combine with fluids from the accessory glands to form semen, and are deposited through the penis. Each structure has a different role, but successful reproduction depends on the structures working together in the correct sequence.",
            "Fertility problems and monitoring may be investigated as research topics. This section does not provide instructions for examining, testing, treating, collecting semen from or handling bulls. Teacher to confirm any local learning activity, animal-care requirement or practical boundary."
          ],
