            "Testosterone supports sperm formation, libido, the male reproductive tract and secondary sexual characteristics.",
            "The testes must remain cooler than normal body temperature for healthy sperm production.",
            "Heat, injury, infection or changed breeding results may suggest a fertility concern, but observations alone do not establish a diagnosis."
